INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(850, 'cubicle', '/ˈkjuːbɪkəl/', 'noun', '{"zh-TW":["辦公隔間"],"en":["a small partitioned-off area in an open-plan office"]}', NULL, 'work in a cubicle / cubicle office layout', '[{"en":"She decorated her cubicle with photos and plants.","zh-TW":"她用照片和植物裝飾了她的辦公隔間。"},{"en":"Open offices replaced the traditional cubicle layout.","zh-TW":"開放式辦公室取代了傳統的隔間式佈局。"}]', NULL, NULL, 3, 850, NULL),
(851, 'cuisine', '/kwɪˈziːn/', 'noun', '{"zh-TW":["料理；烹飪風格"],"en":["a style or method of cooking"]}', NULL, 'Italian cuisine / local cuisine', '[{"en":"The restaurant specializes in Japanese cuisine.","zh-TW":"這家餐廳專門供應日本料理。"},{"en":"The hotel features restaurants offering five different cuisines.","zh-TW":"飯店設有提供五種不同料理的餐廳。"}]', '{"adjective":"culinary"}', NULL, 3, 851, NULL),
(852, 'cultivate', '/ˈkʌltɪveɪt/', 'verb', '{"zh-TW":["培養；培育","培養；耕種"],"en":["to develop or improve by education or training","to grow plants","to develop a quality or skill"]}', '{"root":{"text":"cult","meaning":"tend/grow (耕種)"},"suffix":{"text":"-ivate","meaning":"to make (使)"},"logic":"使耕種成長，即「培養」。"}', 'cultivate relationships/skills/talent; cultivate relationships / cultivate land', '[{"en":"We cultivate long-term relationships with our partners.","zh-TW":"我們培養與合作夥伴的長期關係。"},{"en":"The program helps cultivate future leaders.","zh-TW":"該計畫幫助培養未來的領導者。"},{"en":"Farmers cultivate rice in this region.","zh-TW":"農民在這個地區種植稻米。"},{"en":"She cultivated strong relationships with clients.","zh-TW":"她培養了與客戶的良好關係。"}]', '{"noun":"cultivation"}', NULL, 3, 852, 664),
(853, 'cultural', '/ˈkʌltʃərəl/', 'adjective', '{"zh-TW":["文化的"],"en":["relating to the ideas and customs of a society"]}', NULL, 'cultural difference / cultural exchange', '[{"en":"There are cultural differences between countries.","zh-TW":"國家之間存在文化差異。"},{"en":"The city offers many cultural activities.","zh-TW":"這座城市提供許多文化活動。"}]', '{"noun":"culture","adverb":"culturally"}', NULL, 3, 853, NULL),
(854, 'culture', 'ˈkʌltʃər', 'noun', '{"zh-TW":["文化；企業文化","培養"],"en":["the customs of a group","the beliefs and practices of a company"]}', NULL, 'company culture/cultural diversity', '[{"en":"Our company culture values teamwork.","zh-TW":"我們的公司文化重視團隊合作。"}]', '{"adjective":"cultural","adverb":"culturally"}', NULL, 3, 854, NULL),
(855, 'cup', '/kʌp/', 'noun', '{"zh-TW":["杯子"],"en":["a small container for drinking"]}', NULL, 'cup of tea / World Cup', '[{"en":"Would you like a cup of tea?","zh-TW":"你想來杯茶嗎？"},{"en":"The World Cup is held every four years.","zh-TW":"世界盃每四年舉行一次。"}]', NULL, NULL, 1, 855, NULL),
(856, 'curator', '/kjʊˈreɪtər/', 'noun', '{"zh-TW":["策展人；館長"],"en":["a person in charge of a museum or gallery collection"]}', '{"root":{"text":"cur","meaning":"care (照料)"},"suffix":{"text":"-ator","meaning":"person who (…的人)"},"logic":"照料收藏品的人，即「策展人」。"}', 'museum curator / guest curator', '[{"en":"The curator organized a new exhibition.","zh-TW":"策展人組織了一場新展覽。"},{"en":"She works as a curator at the national museum.","zh-TW":"她在國家博物館擔任策展人。"}]', '{"verb":"curate","noun":"curation"}', NULL, 3, 856, NULL),
(857, 'curb', '/kɜːrb/', 'verb', '{"zh-TW":["抑制；控制"],"en":["to restrain or keep in check"]}', '{"root":{"text":"curb","meaning":"curve/bend (彎曲)"},"logic":"彎曲拉回，即「抑制」。"}', 'curb spending/inflation/emissions', '[{"en":"The government introduced measures to curb inflation.","zh-TW":"政府推出了抑制通膨的措施。"},{"en":"We need to curb unnecessary spending.","zh-TW":"我們需要控制不必要的支出。"}]', NULL, NULL, 1, 857, NULL),
(858, 'cure', '/kjʊr/', 'noun', '{"zh-TW":["治療；療法"],"en":["a treatment that makes someone well"]}', NULL, 'cure for / no cure', '[{"en":"There is no cure for this disease yet.","zh-TW":"這種疾病目前還沒有治療方法。"},{"en":"Prevention is better than cure.","zh-TW":"預防勝於治療。"}]', '{"verb":"cure","adjective":"curable"}', NULL, 1, 858, NULL),
(859, 'curious', '/ˈkjʊriəs/', 'adjective', '{"zh-TW":["好奇的"],"en":["wanting to know or learn something","eager to know or learn something"]}', '{"root":{"text":"cur","meaning":"care (關心)"},"suffix":{"text":"-ious","meaning":"full of (充滿)"},"logic":"充滿關心想了解的，即「好奇的」。"}', 'curious about / curious mind', '[{"en":"Children are naturally curious.","zh-TW":"孩子們天生好奇。"},{"en":"I''m curious about your trip.","zh-TW":"我很好奇你的旅行。"},{"en":"Children are naturally curious about the world.","zh-TW":"孩子天生對世界充滿好奇。"},{"en":"I''m curious to know what happened.","zh-TW":"我很好奇發生了什麼事。"}]', '{"noun":"curiosity","adverb":"curiously"}', NULL, 3, 859, NULL),
(860, 'currency', '/ˈkʌrənsi/', 'noun', '{"zh-TW":["貨幣；通貨"],"en":["a system of money in general use"]}', '{"root":{"text":"curr","meaning":"run (流通)"},"suffix":{"text":"-ency","meaning":"state (狀態)"},"logic":"流通的狀態，即「貨幣」。"}', 'foreign currency / currency exchange / digital currency', '[{"en":"Please specify payment in local currency.","zh-TW":"請以當地貨幣指定付款。"},{"en":"Currency exchange rates fluctuate daily.","zh-TW":"匯率每天波動。"}]', NULL, NULL, 3, 860, 850),
(861, 'current', '/ˈkʌrənt/', 'adjective', '{"zh-TW":["【主要意義-形容詞】現在的；當前的","【次要意義-名詞】水流；氣流；洋流","【次要意義-名詞】電流","【次要意義-名詞】潮流；趨勢"],"en":["[primary - adjective] happening or existing at the present time","[secondary - noun] a steady flow of water, air, or electricity","[secondary - noun] the general trend or direction of events"]}', '{"root":{"text":"curr","meaning":"run (流動)"},"suffix":{"text":"-ent","meaning":"being (存在的)"},"logic":"正在流動存在的，即「目前的」。"}', 'current account / current affairs / alternating current / against the current', '[{"en":"The current account shows a surplus for the third consecutive quarter.","zh-TW":"往來帳戶連續第三季顯示盈餘。"},{"en":"Swimming against the current requires twice as much effort.","zh-TW":"逆流而游需要付出兩倍的努力。"},{"en":"The company must adapt to current trends in digital marketing.","zh-TW":"公司必須適應數位行銷的當前趨勢。"}]', '{"adverb":"currently","noun":"currency"}', 'current account（往來帳戶）是 TOEIC 銀行業文章必考詞，current 作名詞表「電流/水流/趨勢」，currency（貨幣）源於同一詞根，這些用法容易被忽略。', 3, 861, NULL),
(862, 'curriculum', '/kəˈrɪkjʊləm/', 'noun', '{"zh-TW":["課程；課程表"],"en":["the subjects in a course of study"]}', NULL, 'curriculum vitae / training curriculum; school curriculum / curriculum design', '[{"en":"Please submit your curriculum vitae.","zh-TW":"請提交你的履歷。"},{"en":"The training curriculum covers all essentials.","zh-TW":"培訓課程涵蓋了所有必備項目。"},{"en":"The school updated its curriculum.","zh-TW":"學校更新了課程。"},{"en":"Math is part of the core curriculum.","zh-TW":"數學是核心課程的一部分。"}]', '{"noun":"curriculum","adjective":"curricular","adjective2":"extracurricular"}', NULL, 4, 862, NULL),
(863, 'curve', '/kɜːrv/', 'noun', '{"zh-TW":["曲線；彎道"],"en":["a smooth bending line"]}', NULL, 'learning curve / sharp curve', '[{"en":"There''s a sharp curve in the road.","zh-TW":"路上有一個急彎。"},{"en":"The learning curve is steep.","zh-TW":"學習曲線很陡峭。"}]', '{"adjective":"curved"}', NULL, 2, 863, NULL),
(864, 'custody', '/ˈkʌstədi/', 'noun', '{"zh-TW":["保管；監護","監護權；拘留"],"en":["the protective care or guardianship of something","the legal right to care for a child; being held by police"]}', '{"root":{"text":"cust","meaning":"guard (守護)"},"suffix":{"text":"-ody","meaning":"state (狀態)"},"logic":"守護的狀態，即「保管」。"}', 'in custody / custody of assets / safe custody; in custody / child custody', '[{"en":"Securities are held in safe custody by the bank.","zh-TW":"證券由銀行安全保管。"},{"en":"The documents are in the custody of the legal department.","zh-TW":"文件由法務部門保管。"},{"en":"She was awarded custody of the children.","zh-TW":"她獲得了孩子的監護權。"},{"en":"The suspect is in police custody.","zh-TW":"嫌疑人被警方拘留。"}]', '{"noun":"custodian"}', NULL, 3, 864, NULL),
(865, 'custom', '/ˈkʌstəm/', 'noun', '{"zh-TW":["習慣；海關","客製"],"en":["a traditional practice","duties charged on imports/exports"]}', '{"root":{"text":"custom","meaning":"habit/accustomed (習慣)"},"logic":"習慣的做法，即「習慣、海關」。"}', 'customs duty / local customs / custom-made', '[{"en":"The goods were held at customs for inspection.","zh-TW":"貨物在海關被扣留檢查。"},{"en":"We offer custom solutions tailored to your needs.","zh-TW":"我們提供量身定制的客製化解決方案。"}]', '{"noun":"customer","adjective":"customary","verb":"customize"}', NULL, 2, 865, NULL),
(866, 'customer', '/ˈkʌstəmər/', 'noun', '{"zh-TW":["顧客","顧客；客戶"],"en":["a person who buys goods or services"]}', '{"root":{"text":"custom","meaning":"habit (習慣)"},"suffix":{"text":"-er","meaning":"person who (…的人)"},"logic":"有消費習慣的人，即「顧客」。"}', 'regular customer / customer service; customer service / loyal customer', '[{"en":"The customer is always right.","zh-TW":"顧客永遠是對的。"},{"en":"We value our loyal customers.","zh-TW":"我們重視忠實顧客。"},{"en":"The customer asked for a refund.","zh-TW":"顧客要求退款。"}]', '{"noun":"custom","adjective":"customary"}', NULL, 3, 866, 317),
(867, 'customize', 'ˈkʌstəmaɪz', 'verb', '{"zh-TW":["客製化；定制","個性化"],"en":["to modify to specific needs","to personalize"]}', NULL, 'customize a product/customize a service', '[{"en":"We can customize the service to your needs.","zh-TW":"我們可以根據您的需求定制服務。"}]', '{"noun":"customization","adjective":"customized"}', NULL, 3, 867, 318),
(868, 'customs', '/ˈkʌstəmz/', 'noun', '{"zh-TW":["海關"],"en":["the official process of checking goods entering a country"]}', NULL, 'pass through customs / customs declaration', '[{"en":"All passengers must pass through customs upon arrival.","zh-TW":"所有乘客抵達時須通過海關。"},{"en":"Please declare any items over the duty-free limit.","zh-TW":"請申報超過免稅限額的物品。"}]', '{"adjective":"customary"}', NULL, 3, 868, NULL),
(869, 'cut', '/kʌt/', 'verb', '{"zh-TW":["切；削減"],"en":["to divide with a sharp instrument","to reduce"]}', NULL, 'cut costs / cut back', '[{"en":"We need to cut costs by 10%.","zh-TW":"我們需要削減10%的成本。"},{"en":"The company cut 200 jobs.","zh-TW":"公司裁減了200個職位。"}]', '{"verb":"cut","noun":"cut","noun2":"cutback"}', NULL, 1, 869, NULL),
(870, 'cute', '/kjuːt/', 'adjective', '{"zh-TW":["可愛的"],"en":["attractive in a pretty way"]}', NULL, 'cute baby / cute outfit', '[{"en":"What a cute puppy!","zh-TW":"好可愛的小狗！"},{"en":"That''s a cute outfit.","zh-TW":"那套衣服很可愛。"}]', '{"noun":"cuteness"}', NULL, 1, 870, NULL),
(871, 'cutlery', '/ˈkʌtlərɪ/', 'noun', '{"zh-TW":["餐具；刀叉"],"en":["knives, forks, and spoons used for eating"]}', NULL, 'clean cutlery / provide cutlery', '[{"en":"Please set the table with the correct cutlery.","zh-TW":"請用正確的餐具擺好桌子。"},{"en":"The restaurant uses only high-quality cutlery.","zh-TW":"餐廳只使用高品質的餐具。"}]', NULL, NULL, 3, 871, NULL),
(872, 'cybersecurity', '/ˌsaɪbərsɪˈkjʊrɪti/', 'noun', '{"zh-TW":["網路安全"],"en":["protection of computers and networks from attack"]}', NULL, 'cybersecurity threat / cybersecurity expert', '[{"en":"Cybersecurity is a growing concern.","zh-TW":"網路安全是日益受關注的議題。"},{"en":"She works in cybersecurity.","zh-TW":"她從事網路安全工作。"}]', NULL, NULL, 5, 872, NULL),
(873, 'cycle', '/ˈsaɪkl/', 'noun', '{"zh-TW":["週期；循環","循環；周期；自行車"],"en":["a series of events that are regularly repeated","a series of events that repeat"]}', '{"root":{"text":"cycl","meaning":"circle (圓)"},"suffix":{"text":"-e","meaning":"noun ending"},"logic":"圓形的重複，即「週期」。"}', 'business cycle / product life cycle / billing cycle; life cycle / business cycle', '[{"en":"The business cycle affects hiring decisions.","zh-TW":"商業週期影響招聘決策。"},{"en":"The product is at the end of its life cycle.","zh-TW":"產品已處於其生命週期的末端。"},{"en":"The seasons follow a cycle.","zh-TW":"季節遵循一個循環。"},{"en":"She cycles to work every day.","zh-TW":"她每天騎自行車上班。"}]', '{"adjective":"cyclical","verb":"cycle","noun2":"cyclist"}', NULL, 2, 873, NULL),
(874, 'cyclical', '/ˈsɪklɪkəl/', 'adjective', '{"zh-TW":["週期性的；循環的"],"en":["recurring in regular cycles, often related to economic conditions"]}', NULL, 'cyclical industry / cyclical demand / cyclical stock', '[{"en":"Tourism is a highly cyclical industry tied to economic conditions.","zh-TW":"旅遊業是一個高度週期性的行業，與經濟條件密切相關。"},{"en":"Investors reduce exposure to cyclical stocks during downturns.","zh-TW":"在低迷時期，投資者減少對週期性股票的敞口。"}]', '{"adverb":"cyclically","noun":"cycle"}', NULL, 3, 874, NULL),
(875, 'cyclone', '/ˈsaɪkloʊn/', 'noun', '{"zh-TW":["氣旋；颶風"],"en":["a violent rotating windstorm"]}', '{"root":{"text":"cycl","meaning":"circle (圓)"},"suffix":{"text":"-one","meaning":"thing (物)"},"logic":"旋轉如圓的風暴。"}', 'tropical cyclone / cyclone warning', '[{"en":"The cyclone caused widespread destruction.","zh-TW":"氣旋造成大範圍的破壞。"},{"en":"A tropical cyclone is approaching the coast.","zh-TW":"一個熱帶氣旋正在逼近海岸。"}]', '{"adjective":"cyclonic"}', NULL, 3, 875, NULL),
(876, 'dad', '/dæd/', 'noun', '{"zh-TW":["爸爸"],"en":["a father"]}', NULL, 'my dad / dad joke', '[{"en":"My dad taught me to drive.","zh-TW":"我爸爸教我開車。"},{"en":"He''s a great dad.","zh-TW":"他是個好爸爸。"}]', NULL, NULL, 1, 876, NULL),
(877, 'daily', '/ˈdeɪli/', 'adjective', '{"zh-TW":["每日的"],"en":["happening every day"]}', NULL, 'daily routine / daily life', '[{"en":"Exercise is part of my daily routine.","zh-TW":"運動是我日常作息的一部分。"},{"en":"The newspaper is published daily.","zh-TW":"報紙每天出版。"}]', NULL, NULL, 2, 877, NULL),
(878, 'damage', '/ˈdæmɪdʒ/', 'noun / verb', '{"zh-TW":["損害；損壞"],"en":["physical harm that impairs value or usefulness"]}', NULL, 'cause/suffer damage', '[{"en":"The storm caused severe damage to the building.","zh-TW":"暴風雨對建築物造成了嚴重損害。"},{"en":"Smoking can damage your health.","zh-TW":"吸菸會損害你的健康。"}]', '{"noun":"damage","verb":"damage","adjective":"damaged"}', NULL, 2, 878, NULL),
(879, 'damages', '/ˈdæmɪdʒɪz/', 'noun', '{"zh-TW":["損害賠償金"],"en":["money claimed as compensation for loss or injury"]}', NULL, 'claim damages / award damages', '[{"en":"The court awarded damages to the injured party.","zh-TW":"法院向受傷方判決損害賠償金。"},{"en":"The company was ordered to pay damages for breach of contract.","zh-TW":"公司被命令支付違約損害賠償金。"}]', '{"verb":"damage","adjective":"damaged"}', NULL, 3, 879, NULL),
(880, 'dance', '/dæns/', 'verb', '{"zh-TW":["跳舞；舞蹈"],"en":["to move rhythmically to music"]}', NULL, 'dance class / dance floor', '[{"en":"They danced at the company gala.","zh-TW":"他們在公司晚會上跳舞。"},{"en":"She teaches dance classes on weekends.","zh-TW":"她週末教舞蹈課。"}]', '{"verb":"dance","noun":"dance","noun2":"dancer","noun3":"dancing"}', NULL, 2, 880, NULL),
(881, 'danger', '/ˈdeɪndʒər/', 'noun', '{"zh-TW":["危險"],"en":["the possibility of harm or damage","the possibility of harm or death"]}', NULL, 'in danger / danger zone; in danger / out of danger', '[{"en":"Workers are in danger without proper equipment.","zh-TW":"沒有適當裝備，工人會有危險。"},{"en":"There is a danger of flooding.","zh-TW":"有發生洪水的危險。"},{"en":"The building is in danger of collapsing.","zh-TW":"這棟建築有倒塌的危險。"},{"en":"The patient is out of danger now.","zh-TW":"病人已經脫離危險了。"}]', '{"noun":"danger","adjective":"dangerous","adverb":"dangerously","verb":"endanger"}', NULL, 2, 881, NULL),
(882, 'dangerous', 'ˈdeɪndʒərəs', 'adjective', '{"zh-TW":["危險的；有害的","冒險的"],"en":["likely to cause harm","risky"]}', NULL, 'dangerous condition/dangerous product', '[{"en":"The factory reported a dangerous gas leak.","zh-TW":"工廠報告了危險的氣體洩漏。"}]', '{"noun":"danger","adverb":"dangerously"}', NULL, 3, 882, NULL),
(883, 'dark', '/dɑːrk/', 'adjective', '{"zh-TW":["黑暗的；深色的"],"en":["with little or no light","closer to black"]}', NULL, 'in the dark / dark color; in the dark / dark side', '[{"en":"We were kept in the dark about the changes.","zh-TW":"我們被蒙在鼓裡不知道有變動。"},{"en":"She prefers dark colors for business wear.","zh-TW":"她上班穿著偏好深色系。"},{"en":"It gets dark early in winter.","zh-TW":"冬天天黑得早。"},{"en":"She has dark brown hair.","zh-TW":"她有深棕色的頭髮。"}]', '{"adjective":"dark","noun":"darkness","verb":"darken","adverb":"darkly"}', NULL, 1, 883, NULL),
(884, 'data', '/ˈdeɪtə/', 'noun', '{"zh-TW":["資料；數據"],"en":["facts and information collected together"]}', NULL, 'data analysis / big data', '[{"en":"We need more data to decide.","zh-TW":"我們需要更多數據來做決定。"},{"en":"Big data is transforming business.","zh-TW":"大數據正在改變商業。"}]', NULL, NULL, 1, 884, NULL),
(885, 'data-driven', 'ˈdeɪtə ˈdrɪvən', 'adjective', '{"zh-TW":["數據驅動的；基於數據的","以事實為依據的"],"en":["based on analysis of data","using evidence to decide"]}', NULL, 'data-driven decision/data-driven approach', '[{"en":"Our strategy is completely data-driven.","zh-TW":"我們的策略完全基於數據。"}]', NULL, NULL, 4, 885, NULL),
(886, 'database', '/ˈdeɪtəbeɪs/', 'noun', '{"zh-TW":["資料庫"],"en":["an organized collection of stored data"]}', NULL, 'customer database / update the database', '[{"en":"The customer database contains over one million records.","zh-TW":"顧客資料庫包含超過一百萬筆記錄。"},{"en":"Access to the database requires a password.","zh-TW":"訪問資料庫需要密碼。"}]', NULL, NULL, 3, 886, 319),
(887, 'date', 'deɪt', 'noun', '{"zh-TW":["【主要意義-名詞】日期；約會","【次要意義-動詞】過時；使顯得老舊","【次要意義-動詞】追溯到（歷史）；確定年代"],"en":["[primary - noun] a specific day; a romantic appointment","[secondary - verb] to become or appear old-fashioned","[secondary - verb] to determine the age of something; to originate from a time"]}', NULL, 'date back to / out of date / up to date / date from', '[{"en":"This management style is beginning to date and needs updating.","zh-TW":"這種管理風格開始顯得過時，需要更新。"},{"en":"The company dates back to 1923 and has a long trading history.","zh-TW":"該公司可追溯到1923年，有悠久的貿易歷史。"},{"en":"Please ensure all information on the form is up to date.","zh-TW":"請確保表格上的所有資訊都是最新的。"}]', '{"adjective":"dated, outdated"}', '動詞 date 意為「過時」或「追溯到」，片語 date back to（追溯至）和 up to date（最新的）是 TOEIC 閱讀文章和公告中的高頻表達。', 1, 887, NULL),
(888, 'daughter', '/ˈdɔːtər/', 'noun', '{"zh-TW":["女兒"],"en":["a female child"]}', NULL, 'daughter company / eldest daughter; eldest daughter / daughter-in-law', '[{"en":"His daughter works at the same company.","zh-TW":"他的女兒在同一家公司工作。"},{"en":"The daughter company handles overseas sales.","zh-TW":"子公司負責海外銷售。"},{"en":"They have two daughters.","zh-TW":"他們有兩個女兒。"},{"en":"My daughter is ten years old.","zh-TW":"我女兒十歲了。"}]', '{"noun":"daughter"}', NULL, 3, 888, NULL),
(889, 'dead', '/dɛd/', 'adjective', '{"zh-TW":["死的；無生命的"],"en":["no longer alive","not working"]}', NULL, 'deadline / dead end; dead end / dead silence', '[{"en":"My phone battery is dead.","zh-TW":"我的手機沒電了。"},{"en":"The negotiations reached a dead end.","zh-TW":"談判陷入了僵局。"},{"en":"The flowers are dead.","zh-TW":"花都枯死了。"},{"en":"We reached a dead end.","zh-TW":"我們走到了死路。"}]', '{"adjective":"dead","noun":"death","verb":"die","adjective2":"deadly"}', NULL, 1, 889, NULL),
(890, 'deadline', '/ˈdedlaɪn/', 'noun', '{"zh-TW":["截止期限；最後期限","截止期限"],"en":["a date or time by which something must be done","the latest time by which something must be completed"]}', '{"root":{"text":"dead","meaning":"absolute (絕對)"},"suffix":{"text":"line","meaning":"line (線)"},"logic":"絕對不能越過的時間線。"}', 'meet/miss a deadline; meet the deadline / miss the deadline / tight deadline', '[{"en":"The deadline for applications is next Friday.","zh-TW":"申請的截止日期是下週五。"},{"en":"We need to meet the deadline.","zh-TW":"我們必須在截止日期前完成。"},{"en":"The deadline for applications is Friday.","zh-TW":"申請截止日期是週五。"},{"en":"We need to meet the deadline.","zh-TW":"我們需要趕上截止期限。"}]', '{"noun":"deadline"}', NULL, 3, 890, 21),
(891, 'deadline-driven', '/ˈdedlaɪn ˈdrɪvən/', 'adjective', '{"zh-TW":["以截止日期為導向的"],"en":["motivated by or working to specific deadlines"]}', NULL, 'deadline-driven culture / deadline-driven team', '[{"en":"The agency operates in a fast-paced, deadline-driven environment.","zh-TW":"該機構在快節奏、以截止日期為導向的環境中運作。"},{"en":"She thrives in deadline-driven roles where pace is high.","zh-TW":"她在節奏快、以截止日期為導向的職位中表現出色。"}]', NULL, NULL, 5, 891, NULL),
(892, 'deal', '/diːl/', 'noun', '{"zh-TW":["交易；協議"],"en":["an agreement; a bargain"]}', NULL, 'big deal / deal with', '[{"en":"We made a deal.","zh-TW":"我們達成了一筆交易。"},{"en":"It''s not a big deal.","zh-TW":"這沒什麼大不了的。"}]', '{"verb":"deal","noun2":"dealer"}', NULL, 1, 892, 320),
(893, 'dean', '/diːn/', 'noun', '{"zh-TW":["院長；系主任"],"en":["the head of a university department"]}', NULL, 'dean''s list / dean of students', '[{"en":"She was named to the dean''s list.","zh-TW":"她被列入院長嘉許名單。"},{"en":"The dean approved the new course.","zh-TW":"院長批准了新課程。"}]', NULL, NULL, 1, 893, NULL),
(894, 'debate', '/dɪˈbeɪt/', 'noun / verb', '{"zh-TW":["辯論；討論"],"en":["a formal discussion on a particular topic"]}', '{"prefix":{"text":"de-","meaning":"down/thoroughly (徹底)"},"root":{"text":"bat","meaning":"beat (打)"},"logic":"徹底地交鋒辯駁，即「辯論」。"}', 'public/heated debate; heated debate / public debate / open to debate', '[{"en":"There was a heated debate about the new policy.","zh-TW":"關於新政策有一場激烈的辯論。"},{"en":"They debated the issue for hours.","zh-TW":"他們就這個問題辯論了幾個小時。"},{"en":"There is a heated debate about immigration policy.","zh-TW":"關於移民政策有激烈的辯論。"},{"en":"The issue is still open to debate.","zh-TW":"這個議題仍有討論空間。"}]', '{"noun":"debate","verb":"debate","adjective":"debatable"}', NULL, 2, 894, NULL),
(895, 'debenture', '/dɪˈbentʃər/', 'noun', '{"zh-TW":["債券；無擔保債券"],"en":["a type of loan bond not secured by specific assets"]}', NULL, 'issue a debenture / debenture holder / convertible debenture', '[{"en":"The company raised funds through a public debenture issue.","zh-TW":"公司通過公開發行債券籌集了資金。"},{"en":"Debenture holders receive fixed interest regardless of profitability.","zh-TW":"債券持有人無論盈虧都可獲得固定利息。"}]', '{"plural":"debentures","adjective":"debenture"}', NULL, 3, 895, NULL),
(896, 'debit', '/ˈdebɪt/', 'noun', '{"zh-TW":["借方；借記"],"en":["a record of money taken from an account; an accounting entry reducing assets"]}', NULL, 'debit card / debit account / debit entry / direct debit', '[{"en":"Each purchase was recorded as a debit in the ledger.","zh-TW":"每筆購買都在帳本上記錄為借方。"},{"en":"Set up a direct debit to pay bills automatically.","zh-TW":"設定直接借記以自動支付帳單。"}]', '{"verb":"debit","antonym":"credit"}', NULL, 2, 896, NULL),
(897, 'debrief', '/ˌdiːˈbriːf/', 'verb', '{"zh-TW":["彙報；事後討論"],"en":["to question someone after a completed task or event"]}', NULL, 'debrief the team / post-event debrief', '[{"en":"The team met to debrief after the conference.","zh-TW":"團隊在會議後開會進行事後討論。"},{"en":"A thorough debrief helps identify lessons learned.","zh-TW":"徹底的彙報有助於識別所學到的經驗教訓。"}]', '{"noun":"debrief","adjective":"debriefed"}', NULL, 3, 897, NULL),
(898, 'debt', '/det/', 'noun', '{"zh-TW":["債務；欠款"],"en":["money that is owed to someone"]}', NULL, 'pay off/be in debt', '[{"en":"He is struggling to pay off his debts.","zh-TW":"他正努力償還債務。"},{"en":"The company is heavily in debt.","zh-TW":"這家公司負債累累。"}]', '{"noun":"debt/debtor"}', NULL, 1, 898, NULL),
(899, 'debtor', '/ˈdetər/', 'noun', '{"zh-TW":["債務人；借款方"],"en":["a person or company that owes money to another"]}', NULL, 'trade debtor / debtor management / debtor collection', '[{"en":"The company''s debtors owed over two million in total.","zh-TW":"公司的債務人共欠款超過200萬元。"},{"en":"Debtor management software tracks outstanding invoices.","zh-TW":"債務人管理軟體追蹤未付發票。"}]', '{"opposite":"creditor"}', NULL, 2, 899, NULL);
