(900, 'debug', '/diːˈbʌɡ/', 'verb', '{"zh-TW":["除錯"],"en":["to find and fix errors in computer code"]}', NULL, 'debug code / debug mode', '[{"en":"I spent hours debugging the code.","zh-TW":"我花了好幾個小時除錯。"},{"en":"Run it in debug mode.","zh-TW":"用除錯模式執行。"}]', '{"noun":"debugger","noun2":"debugging"}', NULL, 2, 900, NULL),
(901, 'decade', '/ˈdekeɪd/', 'noun', '{"zh-TW":["十年"],"en":["a period of ten years"]}', NULL, 'over the past decade', '[{"en":"The technology has evolved rapidly over the past decade.","zh-TW":"在過去十年中，技術迅速發展。"},{"en":"She spent a decade working overseas.","zh-TW":"她在海外工作了十年。"}]', '{"noun":"decade"}', NULL, 2, 901, NULL),
(902, 'decide', '/dɪˈsaɪd/', 'verb', '{"zh-TW":["決定"],"en":["to make a choice after thinking"]}', NULL, 'decide on / decide to', '[{"en":"We decided to postpone the launch.","zh-TW":"我們決定延後發布。"},{"en":"Have you decided on a venue?","zh-TW":"你決定好場地了嗎？"}]', '{"verb":"decide","noun":"decision","adjective":"decisive","adverb":"decisively"}', NULL, 2, 902, NULL),
(903, 'decision', 'dɪˈsɪʒən', 'noun', '{"zh-TW":["決定；決策","裁決"],"en":["a choice made after consideration","a judgment"]}', NULL, 'make a decision/final decision', '[{"en":"The final decision rests with management.","zh-TW":"最終決定由管理層做出。"}]', '{"verb":"decide","adjective":"decisive","adverb":"decisively"}', NULL, 3, 903, 321),
(904, 'decision-maker', '/dɪˈsɪʒən ˈmeɪkər/', 'noun', '{"zh-TW":["決策者"],"en":["a person with the authority to make important decisions"]}', NULL, 'reach the decision-maker / senior decision-maker', '[{"en":"The sales team struggled to reach the key decision-maker.","zh-TW":"銷售團隊努力聯繫到關鍵決策者。"},{"en":"Always present proposals to the decision-maker directly.","zh-TW":"始終直接向決策者提交提案。"}]', NULL, NULL, 5, 904, NULL),
(905, 'declaration', 'ˌdɛkləˈreɪʃən', 'noun', '{"zh-TW":["宣告；聲明","申報"],"en":["an official statement","a formal announcement"]}', NULL, 'customs declaration/declaration of intent', '[{"en":"Please complete the customs declaration form.","zh-TW":"請填寫海關申報表。"}]', '{"verb":"declare","adjective":"declarative","adverb":"declaratively"}', NULL, 4, 905, 964),
(906, 'declare', '/dɪˈkleər/', 'verb', '{"zh-TW":["申報；宣告"],"en":["to announce officially or formally"]}', NULL, 'declare bankruptcy / declare a dividend / declare income', '[{"en":"The company declared a special dividend of 50 cents per share.","zh-TW":"公司宣佈發放每股50分的特別股利。"},{"en":"All income must be declared on the annual tax return.","zh-TW":"所有收入必須在年度納稅申報表上申報。"}]', '{"noun":"declaration","adjective":"declared"}', NULL, 3, 906, NULL),
(907, 'decline', '/dɪˈklaɪn/', 'verb / noun', '{"zh-TW":["下降；拒絕"],"en":["to decrease in quantity or importance; to politely refuse","to decrease","to politely refuse"]}', '{"prefix":{"text":"de-","meaning":"down (向下)"},"root":{"text":"cline","meaning":"lean (傾斜)"},"logic":"向下傾斜，即「下降」。"}', 'decline an offer/invitation; decline an invitation / sharp decline / decline in', '[{"en":"Sales have declined by 10% this quarter.","zh-TW":"本季度銷售額下降了10%。"},{"en":"She declined the job offer.","zh-TW":"她拒絕了工作邀請。"},{"en":"Sales have declined by 10% this quarter.","zh-TW":"本季銷售額下降了10%。"},{"en":"She politely declined the invitation.","zh-TW":"她禮貌地拒絕了邀請。"}]', '{"noun":"decline","verb":"decline"}', NULL, 3, 907, 97),
(908, 'decommission', '/ˌdiːkəˈmɪʃən/', 'verb', '{"zh-TW":["退役；停用"],"en":["to take a piece of equipment or system out of service permanently"]}', NULL, 'decommission a server / decommission equipment / decommission a plant', '[{"en":"The old data center was decommissioned after the cloud migration.","zh-TW":"雲端遷移後，舊數據中心被退役了。"},{"en":"Decommissioning the factory required careful environmental planning.","zh-TW":"工廠退役需要仔細的環境規劃。"}]', '{"noun":"decommissioning"}', NULL, 4, 908, NULL),
(909, 'decrease', '/dɪˈkriːs/', 'verb / noun', '{"zh-TW":["減少；降低"],"en":["to become smaller or fewer in size or amount"]}', NULL, 'significant/steady decrease', '[{"en":"The number of employees decreased significantly.","zh-TW":"員工人數大幅減少。"},{"en":"There has been a decrease in demand.","zh-TW":"需求有所下降。"}]', '{"noun":"decrease","verb":"decrease"}', NULL, 3, 909, 322),
(910, 'decree', '/dɪˈkriː/', 'noun', '{"zh-TW":["法令；判決"],"en":["an official order issued by a legal authority"]}', NULL, 'royal decree / issue a decree', '[{"en":"The president issued a decree.","zh-TW":"總統頒布了一項法令。"},{"en":"The court issued a divorce decree.","zh-TW":"法院發出了離婚判決。"}]', '{"verb":"decree"}', NULL, 2, 910, NULL),
(911, 'dedicate', '/ˈdedɪkeɪt/', 'verb', '{"zh-TW":["奉獻；致力於"],"en":["to devote time or effort to a particular purpose","to devote time or effort to something"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"dic","meaning":"declare (宣告)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"完全宣告投入，即「奉獻」。"}', 'dedicate oneself to; dedicate time to / dedicated employee', '[{"en":"She dedicated her life to medical research.","zh-TW":"她把一生奉獻給了醫學研究。"},{"en":"He is dedicated to improving customer service.","zh-TW":"他致力於改善客戶服務。"},{"en":"She dedicated her life to helping others.","zh-TW":"她一生奉獻於幫助他人。"},{"en":"He is a dedicated teacher.","zh-TW":"他是一位盡責的老師。"}]', '{"noun":"dedication","verb":"dedicate","adjective":"dedicated"}', NULL, 3, 911, NULL),
(912, 'dedicated', '/ˈdɛdɪkeɪtɪd/', 'adjective', '{"zh-TW":["專注的；專用的；投入的"],"en":["devoted to a task or purpose"]}', NULL, 'dedicated employee / dedicated team', '[{"en":"She is a highly dedicated and reliable team member.","zh-TW":"她是一位高度投入且可靠的團隊成員。"},{"en":"We have a dedicated support team available 24/7.","zh-TW":"我們有一個全天24小時的專用支援團隊。"}]', '{"verb":"dedicate","noun":"dedication"}', NULL, 3, 912, 323),
(913, 'deduct', '/dɪˈdʌkt/', 'verb', '{"zh-TW":["扣除；減去"],"en":["to subtract an amount from a total"]}', NULL, 'deduct from salary/taxes', '[{"en":"Tax is deducted from your salary automatically.","zh-TW":"稅款會自動從薪水中扣除。"},{"en":"You can deduct business expenses from income.","zh-TW":"你可以從收入中扣除商業費用。"}]', '{"noun":"deduction","verb":"deduct","adjective":"deductible"}', NULL, 2, 913, 324),
(914, 'deductible', '/dɪˈdʌktɪbəl/', 'noun', '{"zh-TW":["免賠額；自負額"],"en":["the amount paid before insurance begins to cover costs"]}', NULL, 'annual deductible / high deductible plan', '[{"en":"You must meet your deductible before claims are paid.","zh-TW":"在理賠支付前，您必須達到免賠額。"},{"en":"Choosing a higher deductible lowers your monthly premium.","zh-TW":"選擇較高的免賠額可降低每月保費。"}]', '{"verb":"deduct","adjective":"deductible"}', NULL, 4, 914, 853),
(915, 'deed', '/diːd/', 'noun', '{"zh-TW":["契約；法律文件"],"en":["a signed legal document transferring property or rights"]}', NULL, 'sign a deed / property deed', '[{"en":"The deed to the property was transferred after the sale.","zh-TW":"財產的契約在出售後轉讓了。"},{"en":"A deed of transfer must be witnessed and notarized.","zh-TW":"轉讓契約必須有見證人並公證。"}]', NULL, NULL, 1, 915, NULL),
(916, 'deep', '/diːp/', 'adjective', '{"zh-TW":["深的；深刻的","深的"],"en":["extending far down","very strong or intense","going far down from the surface"]}', NULL, 'deep analysis / in deep trouble; deep water / deep breath', '[{"en":"We need a deeper analysis of the data.","zh-TW":"我們需要更深入的數據分析。"},{"en":"The company is in deep financial trouble.","zh-TW":"公司陷入了嚴重的財務困境。"},{"en":"The river is very deep here.","zh-TW":"河在這裡非常深。"},{"en":"Take a deep breath and relax.","zh-TW":"深呼吸然後放鬆。"}]', '{"adjective":"deep","adverb":"deeply","verb":"deepen","noun":"depth"}', NULL, 1, 916, NULL),
(917, 'default', '/dɪˈfɔːlt/', 'noun / verb', '{"zh-TW":["違約；預設"],"en":["failure to fulfill an obligation; a preset value"]}', NULL, 'by default', '[{"en":"The company defaulted on its loan.","zh-TW":"該公司貸款違約了。"},{"en":"The settings are restored to default.","zh-TW":"設定已恢復為預設值。"}]', '{"noun":"default","verb":"default"}', NULL, 3, 917, 325),
(918, 'defeat', '/dɪˈfiːt/', 'verb / noun', '{"zh-TW":["擊敗；失敗","擊敗；戰勝"],"en":["to win a victory over someone","to win against someone in a fight or game"]}', NULL, 'suffer/admit defeat; suffer a defeat / admit defeat', '[{"en":"They defeated the rival team 3-1.","zh-TW":"他們以3比1擊敗了對手。"},{"en":"He refused to admit defeat.","zh-TW":"他拒絕承認失敗。"},{"en":"They defeated the champions 2-1.","zh-TW":"他們以2比1擊敗了冠軍隊。"}]', '{"noun":"defeat","verb":"defeat"}', NULL, 2, 918, NULL),
(919, 'defend', '/dɪˈfend/', 'verb', '{"zh-TW":["防禦；辯護"],"en":["to protect from harm or danger"]}', NULL, 'defend against', '[{"en":"The lawyer defended her client in court.","zh-TW":"律師在法庭上為她的客戶辯護。"},{"en":"We must defend our market position.","zh-TW":"我們必須捍衛我們的市場地位。"}]', '{"noun":"defense/defendant","verb":"defend","adjective":"defensive"}', NULL, 2, 919, NULL),
(920, 'defendant', '/dɪˈfɛndənt/', 'noun', '{"zh-TW":["被告"],"en":["a person accused in a court of law"]}', NULL, 'the defendant pleaded / defendant''s rights', '[{"en":"The defendant pleaded not guilty.","zh-TW":"被告答辯無罪。"},{"en":"The defendant has the right to an attorney.","zh-TW":"被告有權請律師。"}]', '{"verb":"defend","noun2":"defense"}', NULL, 3, 920, NULL),
(921, 'defer', '/dɪˈfɜːr/', 'verb', '{"zh-TW":["推遲；順從"],"en":["to postpone; to yield to another''s opinion"]}', NULL, 'defer payment/judgment', '[{"en":"Payment has been deferred until next month.","zh-TW":"付款已延遲到下個月。"},{"en":"I defer to your expertise on this matter.","zh-TW":"在這件事上我尊重你的專業意見。"}]', '{"noun":"deferral","verb":"defer"}', NULL, 2, 921, 326),
(922, 'deficiency', '/dɪˈfɪʃənsi/', 'noun', '{"zh-TW":["不足；缺陷"],"en":["a lack or shortage of something required"]}', NULL, 'capital deficiency / skill deficiency / deficiency in controls', '[{"en":"The audit identified a deficiency in the internal approval controls.","zh-TW":"審計發現了內部審批控制方面的缺陷。"},{"en":"A deficiency in working capital was the main cause of the crisis.","zh-TW":"營運資金不足是危機的主要原因。"}]', '{"adjective":"deficient"}', NULL, 4, 922, 1000),
(923, 'deficit', '/ˈdefɪsɪt/', 'noun', '{"zh-TW":["赤字；不足"],"en":["the amount by which something falls short"]}', NULL, 'budget/trade deficit', '[{"en":"The government is trying to reduce the budget deficit.","zh-TW":"政府正在試圖減少預算赤字。"},{"en":"The trade deficit widened last year.","zh-TW":"去年貿易逆差擴大了。"}]', '{"noun":"deficit"}', NULL, 3, 923, 854),
(924, 'define', '/dɪˈfaɪn/', 'verb', '{"zh-TW":["定義；界定"],"en":["to state the exact meaning of something"]}', NULL, 'clearly define', '[{"en":"Please define your objectives clearly.","zh-TW":"請清楚地界定你的目標。"},{"en":"The contract defines the terms of employment.","zh-TW":"合約界定了僱用條件。"}]', '{"noun":"definition","verb":"define","adjective":"definite"}', NULL, 2, 924, 327),
(925, 'deflation', '/dɪˈfleɪʃən/', 'noun', '{"zh-TW":["通貨緊縮"],"en":["a decline in the general price level of goods and services"]}', NULL, 'risk of deflation / deflationary pressure / combat deflation', '[{"en":"Deflation can discourage consumer spending.","zh-TW":"通貨緊縮可能抑制消費者支出。"},{"en":"Japan struggled with deflation for over a decade.","zh-TW":"日本與通貨緊縮鬥爭了超過十年。"}]', '{"adjective":"deflationary","verb":"deflate"}', NULL, 3, 925, NULL),
(926, 'deforestation', '/ˌdiːˌfɒrɪˈsteɪʃən/', 'noun', '{"zh-TW":["森林砍伐；毀林"],"en":["the clearing of forests by humans"]}', NULL, 'stop deforestation / deforestation rate', '[{"en":"Deforestation destroys habitats and contributes to climate change.","zh-TW":"森林砍伐破壞棲地並加劇氣候變遷。"},{"en":"Brazil is working to reduce deforestation in the Amazon.","zh-TW":"巴西正在努力減少亞馬遜的森林砍伐。"}]', '{"verb":"deforest","adjective":"deforested"}', NULL, 5, 926, NULL),
(927, 'degree', '/dɪˈɡriː/', 'noun', '{"zh-TW":["學位；程度；度","學位；程度"],"en":["an academic qualification","an amount or level","a qualification from a university"]}', NULL, 'to a degree / master''s degree; bachelor''s degree / to some degree', '[{"en":"She has a master''s degree in finance.","zh-TW":"她有金融碩士學位。"},{"en":"To what degree is this accurate?","zh-TW":"這在多大程度上是準確的？"},{"en":"She has a degree in engineering.","zh-TW":"她有工程學位。"},{"en":"To some degree, I agree with you.","zh-TW":"在某種程度上，我同意你。"}]', '{"noun":"degree"}', NULL, 2, 927, NULL),
(928, 'DEI', '/ˌdiː iː ˈaɪ/', 'noun', '{"zh-TW":["多元平等共融"],"en":["diversity, equity, and inclusion; efforts to promote fair workplaces"]}', NULL, 'DEI initiatives / DEI policy / DEI training / DEI strategy', '[{"en":"The company appointed a Chief Diversity Officer to lead DEI efforts.","zh-TW":"公司任命了首席多元長來領導多元平等共融工作。"},{"en":"DEI training is now mandatory for all managers.","zh-TW":"多元平等共融培訓現在對所有管理者是強制性的。"}]', '{"full form":"diversity, equity, and inclusion"}', NULL, 1, 928, NULL),
(929, 'delay', '/dɪˈleɪ/', 'verb / noun', '{"zh-TW":["延遲；耽擱"],"en":["to make something happen later than expected"]}', NULL, 'without delay', '[{"en":"The flight was delayed by two hours.","zh-TW":"航班延誤了兩個小時。"},{"en":"Please respond without delay.","zh-TW":"請立即回覆。"}]', '{"noun":"delay","verb":"delay","adjective":"delayed"}', NULL, 2, 929, 328),
(930, 'delegate', '/ˈdelɪɡeɪt/', 'verb / noun', '{"zh-TW":["委派；代表"],"en":["to give a task or responsibility to someone else"]}', NULL, 'delegate authority/tasks', '[{"en":"A good manager knows how to delegate tasks.","zh-TW":"好的管理者知道如何委派任務。"},{"en":"Each country sent a delegate to the conference.","zh-TW":"每個國家都派了代表出席會議。"}]', '{"noun":"delegate/delegation","verb":"delegate"}', NULL, 3, 930, 98),
(931, 'delegation', '/ˌdelɪˈɡeɪʃən/', 'noun', '{"zh-TW":["授權；代表團"],"en":["assigning responsibility and authority to someone else; also a group of representatives"]}', NULL, 'effective delegation / delegation of authority / international delegation', '[{"en":"Effective delegation allows managers to focus on strategic work.","zh-TW":"有效的授權讓管理者能夠專注於策略性工作。"},{"en":"A delegation from three countries attended the trade summit.","zh-TW":"來自三個國家的代表團出席了貿易峰會。"}]', '{"verb":"delegate","adjective":"delegated"}', NULL, 4, 931, 540),
(932, 'deli', '/ˈdɛli/', 'noun', '{"zh-TW":["熟食店；美食店"],"en":["a shop selling prepared foods, meats, and cheeses"]}', NULL, 'local deli / deli counter', '[{"en":"We stopped at the deli to pick up sandwiches for lunch.","zh-TW":"我們在熟食店停下來買了午餐三明治。"},{"en":"The deli offers over 50 varieties of cheese.","zh-TW":"這家熟食店提供超過50種起司。"}]', NULL, NULL, 1, 932, NULL),
(933, 'deliberate', '/dɪˈlɪbərət/', 'adjective / verb', '{"zh-TW":["故意的；審慎的"],"en":["done intentionally; to think carefully","done consciously and intentionally"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"liber","meaning":"weigh (衡量)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"完全經過衡量的，即「審慎的」或「故意的」。"}', 'deliberate action/decision; deliberate action / deliberate decision', '[{"en":"It was a deliberate attempt to mislead investors.","zh-TW":"這是故意誤導投資者的行為。"},{"en":"The jury deliberated for three days.","zh-TW":"陪審團審議了三天。"},{"en":"It was a deliberate attempt to mislead the public.","zh-TW":"這是故意誤導公眾的企圖。"},{"en":"She made a deliberate choice to change careers.","zh-TW":"她審慎地決定轉換職業。"}]', '{"noun":"deliberation","verb":"deliberate","adjective":"deliberate","adverb":"deliberately"}', NULL, 4, 933, 965),
(934, 'delisting', '/diːˈlɪstɪŋ/', 'noun', '{"zh-TW":["摘牌；退市"],"en":["the removal of a company from a stock exchange listing"]}', NULL, 'delist from the exchange / face delisting', '[{"en":"The company faced delisting after failing to meet reporting requirements.","zh-TW":"公司因未能滿足報告要求而面臨退市。"},{"en":"Delisting removed the company from the public markets.","zh-TW":"退市使公司退出了公開市場。"}]', '{"verb":"delist","adjective":"delisted"}', NULL, 3, 934, NULL),
(935, 'deliver', '/dɪˈlɪvər/', 'verb', '{"zh-TW":["遞送；發表"],"en":["to bring goods to a destination; to give a speech","to take something to a person or place"]}', NULL, 'deliver goods/a speech; deliver a speech / deliver goods', '[{"en":"The package will be delivered tomorrow.","zh-TW":"包裹明天會送達。"},{"en":"She delivered an inspiring presentation.","zh-TW":"她發表了一場鼓舞人心的演講。"},{"en":"The package was delivered this morning.","zh-TW":"包裹今天早上送到了。"},{"en":"She delivered an inspiring speech.","zh-TW":"她發表了一場鼓舞人心的演講。"}]', '{"noun":"delivery","verb":"deliver"}', NULL, 3, 935, 99),
(936, 'deliverable', '/dɪˈlɪvərəbl/', 'noun', '{"zh-TW":["可交付成果"],"en":["an output or result that must be produced as part of a project"]}', NULL, 'project deliverable / submit deliverables / key deliverable', '[{"en":"All deliverables must be submitted by the deadline.","zh-TW":"所有可交付成果必須在截止日期前提交。"},{"en":"The contract specifies the deliverables and acceptance criteria.","zh-TW":"合同規定了可交付成果和驗收標準。"}]', '{"plural":"deliverables"}', NULL, 4, 936, 773),
(937, 'delivery', '/dɪˈlɪvəri/', 'noun', '{"zh-TW":["遞送；交付"],"en":["the act of bringing goods to a person"]}', '{"prefix":{"text":"de-","meaning":"away (離開)"},"root":{"text":"liver","meaning":"free (釋放)"},"logic":"釋放出去的行為，即「遞送」。"}', 'free delivery / express delivery', '[{"en":"Delivery takes three to five business days.","zh-TW":"遞送需要三到五個工作天。"},{"en":"We offer free delivery on orders over $50.","zh-TW":"滿50美元免運費。"}]', '{"verb":"deliver"}', NULL, 3, 937, NULL),
(938, 'demand', '/dɪˈmænd/', 'noun / verb', '{"zh-TW":["需求；要求"],"en":["a strong request; the desire for goods or services","a strong request; the desire for goods"]}', NULL, 'meet/supply demand; in demand / supply and demand', '[{"en":"Consumer demand for organic food is growing.","zh-TW":"消費者對有機食品的需求正在增長。"},{"en":"Workers demanded higher wages.","zh-TW":"工人要求更高的工資。"},{"en":"There''s a high demand for nurses.","zh-TW":"對護士的需求很高。"},{"en":"Supply and demand affect prices.","zh-TW":"供需影響價格。"}]', '{"noun":"demand","verb":"demand","adjective":"demanding"}', NULL, 2, 938, NULL),
(939, 'demerger', '/diːˈmɜːrdʒər/', 'noun', '{"zh-TW":["分拆；分離"],"en":["the separation of a company into two or more independent entities"]}', NULL, 'undergo a demerger / complete a demerger', '[{"en":"The conglomerate completed a demerger to unlock separate business values.","zh-TW":"企業集團完成了分拆以釋放各業務的獨立價值。"},{"en":"The demerger allowed each entity to focus on its core competency.","zh-TW":"分拆允許每個實體專注於其核心競爭力。"}]', '{"verb":"demerge"}', NULL, 3, 939, NULL),
(940, 'democracy', '/dɪˈmɒkrəsi/', 'noun', '{"zh-TW":["民主；民主制度","民主"],"en":["government by the people","a system of government by the people"]}', '{"root":{"text":"demo","meaning":"people (人民)"},"suffix":{"text":"cracy","meaning":"rule (統治)"},"logic":"人民統治，即「民主」。"}', 'democratic society / promote democracy; promote democracy / democratic process', '[{"en":"Democracy gives everyone a voice.","zh-TW":"民主賦予每個人發言權。"},{"en":"They fought to protect democracy.","zh-TW":"他們為保護民主而戰。"},{"en":"Democracy gives citizens the right to vote.","zh-TW":"民主賦予公民投票權。"},{"en":"The country transitioned to democracy peacefully.","zh-TW":"該國和平過渡到民主體制。"}]', '{"adjective":"democratic","noun2":"democrat"}', NULL, 3, 940, NULL),
(941, 'demographic', '/ˌdeməˈɡræfɪk/', 'adjective', '{"zh-TW":["人口統計的"],"en":["relating to the statistical characteristics of a population"]}', NULL, 'demographic data / demographic targeting / demographic profile / demographic trends', '[{"en":"The demographic data showed the target audience was primarily aged 25-34.","zh-TW":"人口統計數據顯示目標受眾主要是25至34歲。"},{"en":"Shifting demographics are forcing brands to adapt their messaging.","zh-TW":"人口結構的變化迫使品牌調整其訊息傳遞方式。"}]', '{"noun":"demographics"}', NULL, 4, 941, NULL),
(942, 'demonstrate', '/ˈdemənstreɪt/', 'verb', '{"zh-TW":["展示；證明"],"en":["to show clearly; to prove","to show clearly","to prove by giving evidence"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"monstr","meaning":"show (展示)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"完全展示出來，即「證明」。"}', 'demonstrate ability/skills; demonstrate how / clearly demonstrate', '[{"en":"The data demonstrates a clear trend.","zh-TW":"數據顯示了一個明確的趨勢。"},{"en":"She demonstrated how to use the software.","zh-TW":"她展示了如何使用該軟體。"},{"en":"The experiment demonstrates the theory.","zh-TW":"這個實驗證明了該理論。"},{"en":"Let me demonstrate how to use this tool.","zh-TW":"讓我示範如何使用這個工具。"}]', '{"noun":"demonstration","verb":"demonstrate"}', NULL, 4, 942, 100),
(943, 'demotion', '/dɪˈmoʊʃən/', 'noun', '{"zh-TW":["降職；貶職"],"en":["the reduction of an employee to a lower rank or position"]}', NULL, 'face demotion / voluntary demotion / demotion policy', '[{"en":"He accepted a demotion rather than relocating to another city.","zh-TW":"他接受了降職而不是搬到另一個城市。"},{"en":"Demotion without cause can constitute unfair treatment.","zh-TW":"無故降職可構成不公平對待。"}]', '{"verb":"demote","adjective":"demoted"}', NULL, 3, 943, NULL),
(944, 'demurrage', '/dɪˈmɜːrɪdʒ/', 'noun', '{"zh-TW":["滯期費"],"en":["charges for keeping a ship or container beyond the agreed time"]}', NULL, 'incur demurrage / pay demurrage / demurrage charges', '[{"en":"The company was charged demurrage for holding the container too long.","zh-TW":"公司因持有貨櫃過久而被收取滯期費。"},{"en":"Demurrage charges accumulated while the port was congested.","zh-TW":"港口擁堵期間滯期費不斷累積。"}]', NULL, NULL, 3, 944, NULL),
(945, 'demutualization', '/diːˌmjuːtʃuəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["去互助化；股份化"],"en":["the conversion of a mutual organization into a shareholder-owned company"]}', NULL, 'complete the demutualization / demutualization process', '[{"en":"The insurance cooperative underwent demutualization to access capital markets.","zh-TW":"保險合作社進行了去互助化以進入資本市場。"},{"en":"Demutualization distributes shares to existing members of the mutual company.","zh-TW":"去互助化將股份分配給互助公司的現有成員。"}]', '{"verb":"demutualize"}', NULL, 5, 945, NULL),
(946, 'denial', '/dɪˈnaɪəl/', 'noun', '{"zh-TW":["否認；拒絕"],"en":["a refusal to acknowledge something or to grant a request"]}', NULL, 'denial of service / denial of a claim / issue a denial', '[{"en":"The company issued a denial of the allegations in the press.","zh-TW":"公司向媒體發出了對指控的否認聲明。"},{"en":"The claim was met with a denial from the insurance company.","zh-TW":"索賠遭到保險公司拒絕。"}]', '{"verb":"deny","adjective":"denied"}', NULL, 2, 946, NULL),
(947, 'deny', '/dɪˈnaɪ/', 'verb', '{"zh-TW":["否認；拒絕"],"en":["to declare something untrue; to refuse","to refuse to admit the truth of","to refuse to give"]}', '{"prefix":{"text":"de-","meaning":"away (離開)"},"root":{"text":"ny","meaning":"say no (說不)"},"logic":"說不，即「否認」。"}', 'deny access/responsibility; deny the accusation / deny access / cannot deny', '[{"en":"He denied any involvement in the scandal.","zh-TW":"他否認與醜聞有任何關係。"},{"en":"Access was denied due to security reasons.","zh-TW":"由於安全原因，訪問被拒絕。"},{"en":"He denied all the accusations.","zh-TW":"他否認了所有指控。"},{"en":"They denied him access to the building.","zh-TW":"他們拒絕讓他進入大樓。"}]', '{"noun":"denial","verb":"deny"}', NULL, 1, 947, NULL),
(948, 'depart', '/dɪˈpɑːrt/', 'verb', '{"zh-TW":["離開；出發"],"en":["to leave, especially on a journey"]}', NULL, 'depart from', '[{"en":"The train departs at 8:00 AM.","zh-TW":"火車早上8點出發。"},{"en":"She departed from the original plan.","zh-TW":"她偏離了原來的計畫。"}]', '{"noun":"departure","verb":"depart"}', NULL, 2, 948, NULL),
(949, 'department', '/dɪˈpɑːrtmənt/', 'noun', '{"zh-TW":["部門；科系"],"en":["a division of a large organization or store"]}', '{"prefix":{"text":"de-","meaning":"apart (分開)"},"root":{"text":"part","meaning":"part (部分)"},"suffix":{"text":"-ment","meaning":"result (結果)"},"logic":"分開成各部分的結果，即「部門」。"}', 'department store / sales department', '[{"en":"The electronics department is on the second floor.","zh-TW":"電子產品部在二樓。"},{"en":"She works in the marketing department.","zh-TW":"她在行銷部門工作。"}]', '{"adjective":"departmental"}', NULL, 4, 949, 22);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(950, 'departure', '/dɪˈpɑːrtʃər/', 'noun', '{"zh-TW":["出發；離開"],"en":["the action of leaving a place"]}', NULL, 'departure time / departure gate', '[{"en":"The departure time has been moved up by one hour.","zh-TW":"出發時間提前了一小時。"},{"en":"Please proceed to the departure gate immediately.","zh-TW":"請立即前往登機門。"}]', '{"verb":"depart","adjective":"departing"}', NULL, 3, 950, 23),
(951, 'depend', '/dɪˈpend/', 'verb', '{"zh-TW":["依賴；取決於"],"en":["to rely on; to be determined by","to rely on","to be determined by"]}', '{"prefix":{"text":"de-","meaning":"from (從)"},"root":{"text":"pend","meaning":"hang (懸掛)"},"logic":"懸掛在某物上依靠它，即「依賴」。"}', 'depend on/upon; depend on / it depends / depending on', '[{"en":"The outcome depends on several factors.","zh-TW":"結果取決於幾個因素。"},{"en":"You can depend on her to finish the task.","zh-TW":"你可以依賴她完成任務。"},{"en":"The outcome depends on many factors.","zh-TW":"結果取決於很多因素。"},{"en":"Children depend on their parents.","zh-TW":"孩子依賴他們的父母。"}]', '{"noun":"dependence/dependency","verb":"depend","adjective":"dependent/dependable","adjective2":"dependable"}', NULL, 2, 951, NULL),
(952, 'dependency', '/dɪˈpendənsi/', 'noun', '{"zh-TW":["依賴關係；相依性"],"en":["a task or factor that relies on another being completed first"]}', NULL, 'project dependency / identify dependencies / task dependency / manage dependencies', '[{"en":"The delay in design created a dependency issue for the developers.","zh-TW":"設計延遲為開發人員創造了依賴關係問題。"},{"en":"Critical dependencies must be identified early in project planning.","zh-TW":"關鍵依賴關係必須在項目規劃早期識別。"}]', '{"plural":"dependencies","adjective":"dependent"}', NULL, 4, 952, NULL),
(953, 'deploy', '/dɪˈplɔɪ/', 'verb', '{"zh-TW":["部署；調配"],"en":["to put into use; also to distribute software or systems"]}', NULL, 'deploy resources / deploy software / deploy staff', '[{"en":"The IT team deployed the new system over the weekend.","zh-TW":"IT團隊在週末部署了新系統。"},{"en":"Additional staff were deployed to handle the holiday rush.","zh-TW":"調配了額外人員處理節假日的業務高峰。"}]', '{"noun":"deployment","adjective":"deployed"}', NULL, 2, 953, 735),
(954, 'deployment', '/dɪˈplɔɪmənt/', 'noun', '{"zh-TW":["部署；實施"],"en":["the process of making a system, software, or plan operational"]}', NULL, 'software deployment / deployment plan / production deployment', '[{"en":"The deployment of the new system went smoothly over the weekend.","zh-TW":"新系統的部署在週末順利完成。"},{"en":"A rollback plan was prepared in case the deployment failed.","zh-TW":"準備了回滾計劃以防部署失敗。"}]', '{"verb":"deploy","adjective":"deployed"}', NULL, 4, 954, 542),
(955, 'deposit', '/dɪˈpɑːzɪt/', 'noun / verb', '{"zh-TW":["存款；押金；存放"],"en":["money placed in a bank; to put money into an account"]}', NULL, 'make a deposit', '[{"en":"I need to make a deposit at the bank.","zh-TW":"我需要去銀行存款。"},{"en":"A deposit of $500 is required.","zh-TW":"需要500美元的押金。"}]', '{"noun":"deposit","verb":"deposit"}', NULL, 3, 955, 329),
(956, 'depreciate', '/dɪˈpriːʃieɪt/', 'verb', '{"zh-TW":["貶值；折舊"],"en":["to decrease in value over time"]}', NULL, 'depreciate in value', '[{"en":"The car depreciated quickly after purchase.","zh-TW":"這輛車購買後迅速貶值。"},{"en":"Equipment depreciates over its useful life.","zh-TW":"設備在其使用壽命內折舊。"}]', '{"noun":"depreciation","verb":"depreciate"}', NULL, 4, 956, 666),
(957, 'depreciation', '/dɪˌpriːʃiˈeɪʃən/', 'noun', '{"zh-TW":["折舊；貶值"],"en":["a decrease in value over time"]}', NULL, 'asset depreciation / annual depreciation', '[{"en":"We account for annual depreciation of equipment.","zh-TW":"我們計算設備的年度折舊。"},{"en":"Currency depreciation affects import costs.","zh-TW":"貨幣貶值影響進口成本。"}]', '{"noun":"depreciation","verb":"depreciate"}', NULL, 4, 957, 775),
(958, 'depressed', '/dɪˈprest/', 'adjective', '{"zh-TW":["沮喪的；憂鬱的"],"en":["in a state of unhappiness"]}', '{"prefix":{"text":"de-","meaning":"down (向下)"},"root":{"text":"press","meaning":"press (壓)"},"suffix":{"text":"-ed","meaning":"state (狀態)"},"logic":"被向下壓的狀態，即「沮喪的」。"}', 'feel depressed / clinically depressed', '[{"en":"He felt depressed after losing his job.","zh-TW":"失業後他感到很沮喪。"},{"en":"If you feel depressed, seek professional help.","zh-TW":"如果你感到憂鬱，請尋求專業協助。"}]', '{"noun":"depression","verb":"depress","adjective":"depressing"}', NULL, 3, 958, NULL),
(959, 'deputy', '/ˈdepjʊti/', 'noun', '{"zh-TW":["副職；代理人"],"en":["a person second in command or authorized to act for a senior"]}', NULL, 'appoint a deputy / act as deputy / deputy director', '[{"en":"The deputy was authorized to sign contracts in the director''s absence.","zh-TW":"副職在主任缺席時被授權簽署合約。"},{"en":"She served as deputy CFO before her promotion.","zh-TW":"她在晉升前擔任副財務長。"}]', '{"adjective":"deputy","plural":"deputies"}', NULL, 2, 959, NULL),
(960, 'deregulation', '/diːˌrɛɡjʊˈleɪʃən/', 'noun', '{"zh-TW":["解除管制；放鬆管制"],"en":["the removal of government regulations from an industry"]}', NULL, 'support deregulation / financial deregulation', '[{"en":"Deregulation of the airline industry led to lower ticket prices.","zh-TW":"航空業的解除管制導致機票價格下降。"},{"en":"The government initiated deregulation to stimulate competition.","zh-TW":"政府啟動解除管制以刺激競爭。"}]', '{"verb":"deregulate"}', NULL, 4, 960, NULL),
(961, 'derivative', '/dɪˈrɪvətɪv/', 'noun', '{"zh-TW":["衍生性金融商品"],"en":["a financial instrument whose value is based on an underlying asset"]}', NULL, 'financial derivative / derivative contract / trade derivatives', '[{"en":"Derivatives can be used to hedge against currency risk.","zh-TW":"衍生性商品可用於對沖貨幣風險。"},{"en":"The bank''s exposure to derivatives raised regulatory concerns.","zh-TW":"銀行對衍生性商品的敞口引發了監管擔憂。"}]', '{"adjective":"derivative"}', NULL, 4, 961, 776),
(962, 'derive', '/dɪˈraɪv/', 'verb', '{"zh-TW":["源自；獲得"],"en":["to obtain from a source; to originate"]}', NULL, 'derive from', '[{"en":"The word derives from Latin.","zh-TW":"這個詞源自拉丁語。"},{"en":"We derive great satisfaction from our work.","zh-TW":"我們從工作中獲得極大的滿足感。"}]', '{"noun":"derivation/derivative","verb":"derive"}', NULL, 2, 962, NULL),
(963, 'dermatology', '/ˌdɜːrmɪˈtɒlədʒi/', 'noun', '{"zh-TW":["皮膚科；皮膚病學"],"en":["the branch of medicine dealing with skin conditions"]}', NULL, 'dermatology clinic / consult a dermatologist', '[{"en":"She visited the dermatology clinic for a skin allergy.","zh-TW":"她前往皮膚科診所治療皮膚過敏。"},{"en":"Dermatology treatments range from acne care to cancer screening.","zh-TW":"皮膚科治療範圍從痤瘡護理到癌症篩查。"}]', '{"noun":"dermatologist","adjective":"dermatological"}', NULL, 4, 963, NULL),
(964, 'describe', '/dɪˈskraɪb/', 'verb', '{"zh-TW":["描述；形容","描述"],"en":["to give a detailed account of something","to say what something is like"]}', NULL, 'describe as; describe as / hard to describe', '[{"en":"Can you describe the suspect?","zh-TW":"你能描述一下嫌疑人嗎？"},{"en":"She described the experience as life-changing.","zh-TW":"她形容這次經歷改變了她的人生。"},{"en":"Can you describe what happened?","zh-TW":"你能描述發生了什麼嗎？"},{"en":"Words cannot describe my feelings.","zh-TW":"言語無法描述我的感受。"}]', '{"noun":"description","verb":"describe","adjective":"descriptive"}', NULL, 3, 964, 24),
(965, 'description', 'dɪˈskrɪpʃən', 'noun', '{"zh-TW":["描述；說明","職位說明"],"en":["an account of qualities or features","a written account"]}', NULL, 'job description/product description', '[{"en":"The job description requires five years of experience.","zh-TW":"職位說明要求五年工作經驗。"}]', '{"verb":"describe","adjective":"descriptive","adverb":"descriptively"}', NULL, 4, 965, 330),
(966, 'deserve', '/dɪˈzɜːrv/', 'verb', '{"zh-TW":["值得；應得"],"en":["to be worthy of something","to be worthy of reward or punishment"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"serve","meaning":"serve (服務)"},"logic":"完全服務付出而應得的。"}', 'deserve recognition/attention; deserve recognition / deserve better / well-deserved', '[{"en":"She deserves a promotion for her hard work.","zh-TW":"她努力工作，值得升職。"},{"en":"This issue deserves more attention.","zh-TW":"這個問題值得更多關注。"},{"en":"She deserves a promotion for her hard work.","zh-TW":"她努力工作，值得升遷。"},{"en":"The team deserves recognition for their efforts.","zh-TW":"團隊的努力值得肯定。"}]', '{"adjective":"deserving","verb":"deserve"}', NULL, 3, 966, NULL),
(967, 'design', '/dɪˈzaɪn/', 'noun / verb', '{"zh-TW":["設計；計畫","設計"],"en":["to plan and create something; a drawing or plan","the art of making plans for something"]}', NULL, 'design a product/system; graphic design / by design', '[{"en":"She designed the company''s new logo.","zh-TW":"她設計了公司的新標誌。"},{"en":"The building has an innovative design.","zh-TW":"這棟建築有創新的設計。"},{"en":"She studied fashion design.","zh-TW":"她學了時裝設計。"}]', '{"noun":"design/designer","verb":"design","noun2":"designer"}', NULL, 2, 967, NULL),
(968, 'designate', '/ˈdezɪɡneɪt/', 'verb', '{"zh-TW":["指定；指派"],"en":["to officially assign a status or name"]}', NULL, 'designate as', '[{"en":"This area has been designated as a no-smoking zone.","zh-TW":"此區域已被指定為禁菸區。"},{"en":"She was designated as team leader.","zh-TW":"她被指派為團隊負責人。"}]', '{"noun":"designation","verb":"designate","adjective":"designated"}', NULL, 3, 968, 101),
(969, 'designation', '/ˌdezɪɡˈneɪʃən/', 'noun', '{"zh-TW":["指定；名稱；稱謂"],"en":["the act of officially assigning a name, role, or status to something"]}', NULL, 'job designation / formal designation / receive a designation', '[{"en":"Her job designation is Senior Vice President of Marketing.","zh-TW":"她的職稱是行銷高級副總裁。"},{"en":"The area received a designation as a special economic zone.","zh-TW":"該地區獲得了特別經濟區的指定。"}]', '{"verb":"designate","adjective":"designated"}', NULL, 4, 969, 543),
