(971, 'desk', '/dɛsk/', 'noun', '{"zh-TW":["書桌；辦公桌"],"en":["a table for working at"]}', NULL, 'front desk / help desk', '[{"en":"Please check in at the front desk.","zh-TW":"請在前台登記。"},{"en":"Contact the help desk for IT issues.","zh-TW":"如有IT問題請聯繫服務台。"}]', '{"noun":"desk"}', NULL, 1, 971, NULL),
(972, 'despite', '/dɪˈspaɪt/', 'preposition', '{"zh-TW":["儘管；不顧"],"en":["without being affected by; in spite of"]}', NULL, 'despite the fact that', '[{"en":"Despite the rain, the event was a success.","zh-TW":"儘管下雨，活動還是很成功。"},{"en":"She succeeded despite many obstacles.","zh-TW":"儘管有許多障礙，她還是成功了。"}]', NULL, NULL, 3, 972, NULL),
(973, 'dessert', '/dɪˈzɜːrt/', 'noun', '{"zh-TW":["甜點；飯後甜食"],"en":["a sweet food eaten after the main course"]}', NULL, 'dessert menu / order dessert', '[{"en":"The dessert menu includes chocolate cake and ice cream.","zh-TW":"甜點菜單包含巧克力蛋糕和冰淇淋。"},{"en":"Would you like to see the dessert menu?","zh-TW":"您想看看甜點菜單嗎？"}]', NULL, NULL, 3, 973, NULL),
(974, 'destination', '/ˌdestɪˈneɪʃən/', 'noun', '{"zh-TW":["目的地"],"en":["the place to which someone is going"]}', '{"root":{"text":"destin","meaning":"determine (決定)"},"suffix":{"text":"-ation","meaning":"place (地方)"},"logic":"決定要去的地方，即「目的地」。"}', 'tourist/popular destination; popular destination / final destination / travel destination', '[{"en":"We arrived at our destination on time.","zh-TW":"我們準時到達了目的地。"},{"en":"Paris is a popular tourist destination.","zh-TW":"巴黎是熱門的旅遊目的地。"},{"en":"Paris is a popular tourist destination.","zh-TW":"巴黎是熱門旅遊目的地。"},{"en":"We arrived at our destination at noon.","zh-TW":"我們中午抵達目的地。"}]', '{"noun":"destination"}', NULL, 4, 974, NULL),
(975, 'destroy', '/dɪˈstrɔɪ/', 'verb', '{"zh-TW":["摧毀；破壞"],"en":["to damage something so badly it no longer exists"]}', NULL, 'destroy completely / destroy evidence', '[{"en":"The fire destroyed the building.","zh-TW":"大火摧毀了建築物。"},{"en":"War destroys lives and communities.","zh-TW":"戰爭摧毀生命和社區。"}]', '{"noun":"destruction","adjective":"destructive"}', NULL, 3, 975, NULL),
