(977, 'detailed', 'ˈdiːteɪld', 'adjective', '{"zh-TW":["詳細的；詳盡的","精細的"],"en":["containing many specifics","thorough"]}', NULL, 'detailed report/detailed plan', '[{"en":"Please submit a detailed action plan.","zh-TW":"請提交詳細的行動計畫。"}]', '{"noun":"detail","adverb":"in detail"}', NULL, 3, 977, NULL),
(978, 'detect', '/dɪˈtekt/', 'verb', '{"zh-TW":["偵測；發現"],"en":["to discover or notice something","to discover the presence of something"]}', '{"prefix":{"text":"de-","meaning":"away (除去)"},"root":{"text":"tect","meaning":"cover (覆蓋)"},"logic":"把覆蓋物移除而發現，即「偵測」。"}', 'detect a problem/error; detect a problem / detect changes', '[{"en":"The system detected an error in the data.","zh-TW":"系統偵測到資料中的錯誤。"},{"en":"Cancer can be treated if detected early.","zh-TW":"癌症如果早期發現可以治療。"},{"en":"The sensor can detect small changes in temperature.","zh-TW":"感測器能偵測到微小的溫度變化。"},{"en":"Police detected traces of the substance.","zh-TW":"警方偵測到該物質的痕跡。"}]', '{"noun":"detection/detector","verb":"detect","adjective":"detectable","noun2":"detector"}', NULL, 2, 978, 331),
(979, 'deter', '/dɪˈtɜːr/', 'verb', '{"zh-TW":["阻止；嚇阻"],"en":["to discourage someone from doing something through fear of consequences"]}', NULL, 'deter fraud / deter misconduct / act as a deterrent', '[{"en":"Strong penalties deter companies from cutting safety corners.","zh-TW":"嚴厲的懲罰阻止公司在安全方面偷工減料。"},{"en":"Regular audits deter fraudulent activity in financial reporting.","zh-TW":"定期審計阻止財務報告中的詐欺行為。"}]', '{"noun":"deterrent","adjective":"deterred"}', NULL, 2, 979, NULL),
(980, 'deterioration', '/dɪˌtɪəriəˈreɪʃən/', 'noun', '{"zh-TW":["惡化；品質下降"],"en":["a decline in quality, value, or condition over time"]}', NULL, 'prevent deterioration / rate of deterioration', '[{"en":"Proper storage prevents the deterioration of perishable goods.","zh-TW":"適當的儲存防止了易腐貨物的品質下降。"},{"en":"Deterioration in financial performance triggered a credit review.","zh-TW":"財務業績惡化觸發了信用審查。"}]', '{"verb":"deteriorate","adjective":"deteriorated"}', NULL, 5, 980, NULL),
(981, 'determine', '/dɪˈtɜːrmɪn/', 'verb', '{"zh-TW":["決定；確定"],"en":["to find out; to be the cause of","to find out or establish exactly"]}', NULL, 'determine the cause/outcome; determine the cause / determined to', '[{"en":"We need to determine the cause of the problem.","zh-TW":"我們需要確定問題的原因。"},{"en":"Your score determines your final grade.","zh-TW":"你的分數決定你的最終成績。"},{"en":"We need to determine the cause.","zh-TW":"我們需要確定原因。"},{"en":"She''s determined to succeed.","zh-TW":"她決心要成功。"}]', '{"noun":"determination","verb":"determine","adjective":"determined"}', NULL, 3, 981, 103),
