(983, 'devastating', '/ˈdevəsteɪtɪŋ/', 'adjective', '{"zh-TW":["毀滅性的"],"en":["causing severe damage or destruction"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"vast","meaning":"empty/waste (荒廢)"},"suffix":{"text":"-ating","meaning":"causing (造成)"},"logic":"造成完全荒廢的，即「毀滅性的」。"}', 'devastating effect / devastating news', '[{"en":"The hurricane had a devastating impact on the town.","zh-TW":"颶風對城鎮造成了毀滅性的影響。"},{"en":"The news was devastating for the family.","zh-TW":"這個消息對這家人來說是毀滅性的打擊。"}]', '{"verb":"devastate","noun":"devastation"}', NULL, 4, 983, NULL),
(984, 'develop', '/dɪˈveləp/', 'verb', '{"zh-TW":["發展；開發","開發；發展"],"en":["to grow or cause to grow; to create","to grow or create something over time"]}', NULL, 'develop a plan/product; develop skills / develop a plan', '[{"en":"The company is developing a new product.","zh-TW":"公司正在開發新產品。"},{"en":"Skills develop with practice.","zh-TW":"技能通過練習而發展。"},{"en":"The company developed a new product.","zh-TW":"公司開發了一款新產品。"},{"en":"Children develop at different rates.","zh-TW":"孩子們的發展速度不同。"}]', '{"noun":"development/developer","verb":"develop","noun2":"developer"}', NULL, 3, 984, 104),
