(988, 'devote', '/dɪˈvoʊt/', 'verb', '{"zh-TW":["奉獻；投入"],"en":["to give time or resources to something","to give time, effort, or resources to something"]}', '{"prefix":{"text":"de-","meaning":"completely (完全)"},"root":{"text":"vote","meaning":"vow (發誓)"},"logic":"完全發誓投入，即「奉獻」。"}', 'devote time/energy to; devote time to / devote oneself to', '[{"en":"He devoted his career to public service.","zh-TW":"他把職業生涯奉獻給了公共服務。"},{"en":"She devotes two hours daily to exercise.","zh-TW":"她每天投入兩小時運動。"},{"en":"He devoted his career to scientific research.","zh-TW":"他將職業生涯奉獻給科學研究。"},{"en":"She devotes several hours a week to volunteering.","zh-TW":"她每週投入幾個小時做志工。"}]', '{"noun":"devotion","verb":"devote","adjective":"devoted"}', NULL, 2, 988, NULL),
(989, 'diagnose', '/ˌdaɪəɡˈnoʊz/', 'verb', '{"zh-TW":["診斷"],"en":["to identify a disease or problem"]}', NULL, 'diagnose a condition', '[{"en":"The doctor diagnosed him with diabetes.","zh-TW":"醫生診斷他患有糖尿病。"},{"en":"The technician diagnosed the issue quickly.","zh-TW":"技術人員很快診斷出了問題。"}]', '{"noun":"diagnosis","verb":"diagnose","adjective":"diagnostic"}', NULL, 3, 989, NULL),
